-- Run inside BEGIN / optional candidate DDL / ROLLBACK only
CREATE TEMP TABLE shipping_proof(name text PRIMARY KEY,status text NOT NULL DEFAULT 'PASS');
CREATE FUNCTION pg_temp.shipping_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'Shipping check failed: %',label;END IF;INSERT INTO shipping_proof(name) VALUES(label);END $$;
DO $$
DECLARE cafe uuid;actor uuid;service uuid:=gen_random_uuid();product uuid:=gen_random_uuid();option_id uuid:=gen_random_uuid();other_id uuid:=gen_random_uuid();foreign_cafe uuid;foreign_actor uuid;foreign_option uuid:=gen_random_uuid();account uuid;foreign_account uuid;staff_actor uuid;
  context jsonb;config jsonb;payload jsonb;option jsonb;result jsonb;page2 jsonb;activity jsonb;input jsonb;policy jsonb;invoice_settings jsonb;denied boolean;n integer;doc_count bigint;journal_count bigint;movement_count bigint;
  activity_query jsonb:='{"actions":[],"actorIds":[],"from":"","to":"","direction":"desc","page":1}';today date:=(clock_timestamp() AT TIME ZONE 'Asia/Riyadh')::date;
BEGIN
  SELECT id,owner_user_id INTO STRICT cafe,actor FROM public.cafes WHERE slug='test-cafe';
  SELECT id INTO STRICT account FROM public.bf_accounts WHERE cafe_id=cafe AND active AND kind='revenue' ORDER BY code LIMIT 1;
  SELECT c.id,c.owner_user_id INTO STRICT foreign_cafe,foreign_actor FROM public.cafes c JOIN public.profiles p ON p.id=c.owner_user_id WHERE c.id<>cafe AND c.owner_user_id<>actor AND p.status='active' AND c.deleted_at IS NULL AND c.status IN('active','published') AND platform_access_private.service_enabled(c.id,'finance') AND NOT EXISTS(SELECT 1 FROM public.bf_staff s WHERE s.cafe_id=c.id AND s.user_id=actor AND s.active) LIMIT 1;
  SELECT id INTO foreign_account FROM public.bf_accounts WHERE cafe_id=foreign_cafe AND active AND kind='revenue' LIMIT 1;
  SELECT count(*) INTO doc_count FROM public.bf_documents;SELECT count(*) INTO journal_count FROM public.bf_journal;SELECT count(*) INTO movement_count FROM public.bf_movements;
  PERFORM set_config('request.jwt.claim.sub',actor::text,true);
  context:=public.brand_finance_shipping_settings(cafe);
  PERFORM pg_temp.shipping_assert(context->'settings'='{"enabled":false,"codServiceId":null}'::jsonb AND context->>'revision'='0','disabled default settings');
  INSERT INTO public.menu_products(id,cafe_id,name,price) VALUES(service,cafe,'العنوان الحصري - خدمة اختبار الشحن',18),(product,cafe,'العنوان الحصري - صنف اختبار الشحن',20);
  invoice_settings:=public.brand_finance_invoice_settings(cafe,'get');
  policy:=jsonb_build_object('productId',service,'kind','service','minimumPrice',0,'vatRate',15,'taxCategory','S','exemptionReason','');
  PERFORM public.brand_finance_invoice_settings(cafe,'save',jsonb_set(invoice_settings->'settings','{advanced,productPolicies}',(invoice_settings#>'{settings,advanced,productPolicies}')||jsonb_build_array(policy)),(invoice_settings->>'revision')::integer);
  context:=public.brand_finance_shipping_settings(cafe);
  PERFORM pg_temp.shipping_assert(EXISTS(SELECT 1 FROM jsonb_array_elements(context->'services') s WHERE s->>'id'=service::text) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(context->'services') s WHERE s->>'id'=product::text),'COD choices are real active service products');
  config:=jsonb_build_object('enabled',true,'codServiceId',service);
  result:=public.brand_finance_shipping_settings(cafe,'save',config,0);
  PERFORM pg_temp.shipping_assert(result->>'revision'='1' AND public.brand_finance_shipping_settings(cafe,'save',config,0)=result,'settings persist and lost response retry');
  denied:=false;BEGIN PERFORM public.brand_finance_shipping_settings(cafe,'save',jsonb_set(config,'{enabled}','false'),0);EXCEPTION WHEN serialization_failure THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied,'settings conflict');
  denied:=false;BEGIN PERFORM public.brand_finance_shipping_settings(cafe,'save',jsonb_set(config,'{codServiceId}',to_jsonb(product::text)),1);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied,'ordinary product cannot become COD service');
  UPDATE public.menu_products SET available=false WHERE id=service;
  denied:=false;BEGIN PERFORM public.brand_finance_shipping_settings(cafe,'save',config,1);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied,'inactive service rejected');
  UPDATE public.menu_products SET available=true WHERE id=service;
  payload:=jsonb_build_object('name','العنوان الحصري - خيار اختبار الشحن','active',true,'fee',15,'taxRate',NULL,'displayOrder',1,'accountId',account,'description','العنوان الحصري - وصف اختبار الشحن');
  option:=public.brand_finance_save_shipping_option(cafe,option_id,payload,0);
  PERFORM pg_temp.shipping_assert(option->>'revision'='1' AND option->>'fee'='15.00' AND option->>'accountId'=account::text,'option persists fee account and version');
  PERFORM pg_temp.shipping_assert(public.brand_finance_save_shipping_option(cafe,option_id,payload,0)=option,'create retry no duplicate');
  denied:=false;BEGIN PERFORM public.brand_finance_save_shipping_option(cafe,other_id,payload,0);EXCEPTION WHEN unique_violation THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied,'duplicate active option name rejected');
  denied:=false;BEGIN PERFORM public.brand_finance_save_shipping_option(cafe,option_id,jsonb_set(payload,'{fee}','20'),0);EXCEPTION WHEN serialization_failure THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied,'option revision conflict');
  FOREACH input IN ARRAY ARRAY['[]'::jsonb,payload||'{"unknown":true}'::jsonb,jsonb_set(payload,'{fee}','-1'),jsonb_set(payload,'{fee}','15.111'),jsonb_set(payload,'{taxRate}','5'),jsonb_set(payload,'{displayOrder}','0.5'),jsonb_set(payload,'{name}','" "')] LOOP
    denied:=false;BEGIN PERFORM public.brand_finance_save_shipping_option(cafe,option_id,input,1);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
    IF NOT denied THEN RAISE EXCEPTION 'Invalid option input accepted';END IF;
  END LOOP;
  PERFORM pg_temp.shipping_assert(true,'strict input fees tax and order validation');
  IF foreign_account IS NULL THEN RAISE EXCEPTION 'No foreign revenue account fixture';END IF;
  denied:=false;BEGIN PERFORM public.brand_finance_save_shipping_option(cafe,option_id,jsonb_set(payload,'{accountId}',to_jsonb(foreign_account::text)),1);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied,'foreign account rejected');
  FOR n IN 1..31 LOOP
    input:=jsonb_set(jsonb_set(jsonb_set(payload,'{name}',to_jsonb('العنوان الحصري - شحن مرقم '||lpad(n::text,2,'0'))),'{fee}',to_jsonb(n)),'{displayOrder}',to_jsonb(n+1));
    IF n%2=0 THEN input:=jsonb_set(input,'{active}','false');END IF;
    PERFORM public.brand_finance_save_shipping_option(cafe,gen_random_uuid(),input,0);
  END LOOP;
  input:='{"query":"","status":"all","page":1,"sort":"displayOrder","direction":"asc"}';
  result:=public.brand_finance_shipping_options(cafe,input);page2:=public.brand_finance_shipping_options(cafe,jsonb_set(input,'{page}','2'));
  PERFORM pg_temp.shipping_assert(result->>'total'='32' AND jsonb_array_length(result->'items')=30 AND jsonb_array_length(page2->'items')=2 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(result->'items') a JOIN jsonb_array_elements(page2->'items') b ON a->>'id'=b->>'id'),'bounded list pages do not overlap');
  PERFORM pg_temp.shipping_assert(result#>>'{items,0,id}'=option_id::text,'display order default');
  PERFORM pg_temp.shipping_assert(public.brand_finance_shipping_options(cafe,jsonb_set(input,'{status}','"inactive"'))->>'total'='15','inactive status filter');
  PERFORM pg_temp.shipping_assert(public.brand_finance_shipping_options(cafe,jsonb_set(input,'{query}','"مرقم 31"'))->>'total'='1','name filter');
  PERFORM pg_temp.shipping_assert(public.brand_finance_shipping_options(cafe,jsonb_set(jsonb_set(input,'{sort}','"fee"'),'{direction}','"desc"'))#>>'{items,0,fee}'='31.00','fee sorting descending');
  denied:=false;BEGIN PERFORM public.brand_finance_shipping_options(cafe,jsonb_set(input,'{page}','0'));EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied,'list page validation');
  FOR n IN 1..21 LOOP payload:=jsonb_set(payload,'{fee}',to_jsonb(15+n));option:=public.brand_finance_save_shipping_option(cafe,option_id,payload,n);END LOOP;
  activity:=public.brand_finance_shipping_activity(cafe,option_id);
  result:=public.brand_finance_shipping_activity(cafe,option_id,jsonb_set(activity_query,'{page}','2'));
  PERFORM pg_temp.shipping_assert(jsonb_array_length(activity->'items')=20 AND jsonb_array_length(result->'items')=2 AND result->>'page'='2' AND result->>'total'='22' AND result#>>'{items,1,action}'='created' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(activity->'items') a JOIN jsonb_array_elements(result->'items') b ON a->>'id'=b->>'id'),'activity bounded pages include create and updates without overlap');
  PERFORM pg_temp.shipping_assert(activity#>>'{items,0,actor}' IS NOT NULL AND activity#>>'{items,0,createdAt}' IS NOT NULL AND activity#>>'{items,0,changes,0,field}'='fee' AND (activity#>>'{items,0,changes,0,before}')::numeric=35 AND (activity#>>'{items,0,changes,0,after}')::numeric=36,'actual activity actor time and changed values');
  denied:=false;BEGIN PERFORM public.brand_finance_delete_shipping_option(cafe,option_id,1);EXCEPTION WHEN serialization_failure THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied,'delete revision conflict');
  result:=public.brand_finance_delete_shipping_option(cafe,option_id,22);
  PERFORM pg_temp.shipping_assert(result->>'deleted'='true' AND public.brand_finance_delete_shipping_option(cafe,option_id,22)=result,'delete and retry idempotent');
  PERFORM pg_temp.shipping_assert(public.brand_finance_shipping_options(cafe,input)->>'total'='31' AND public.brand_finance_shipping_activity(cafe,option_id)#>>'{items,0,action}'='deleted','deleted option hidden and activity retained');
  PERFORM pg_temp.shipping_assert(public.brand_finance_shipping_activity(cafe,option_id,jsonb_set(activity_query,'{direction}','"asc"'))#>>'{items,0,revision}'='1','activity ascending direction');
  INSERT INTO public.bf_shipping_events(cafe_id,option_id,revision,action,before_value,after_value,created_by,created_at) VALUES(cafe,option_id,24,'updated','{}','{"name":"العنوان الحصري - اختبار حدود التاريخ"}',foreign_actor,(today+1)::timestamp AT TIME ZONE 'Asia/Riyadh');
  result:=public.brand_finance_shipping_activity(cafe,option_id,jsonb_set(jsonb_set(activity_query,'{from}',to_jsonb(today::text)),'{to}',to_jsonb(today::text)));
  PERFORM pg_temp.shipping_assert(result->>'total'='23','activity Riyadh end date excludes next midnight');
  result:=public.brand_finance_shipping_activity(cafe,option_id,jsonb_set(jsonb_set(jsonb_set(activity_query,'{from}',to_jsonb((today+1)::text)),'{to}',to_jsonb((today+1)::text)),'{actorIds}',jsonb_build_array(foreign_actor)));
  PERFORM pg_temp.shipping_assert(result->>'total'='1' AND result#>>'{items,0,actorId}'=foreign_actor::text,'activity actor and period filters intersect');
  result:=public.brand_finance_shipping_activity(cafe,option_id,jsonb_set(jsonb_set(activity_query,'{actions}','["created","deleted"]'),'{actorIds}',jsonb_build_array(actor)));
  PERFORM pg_temp.shipping_assert(result->>'total'='2' AND jsonb_array_length(result->'actors')=2 AND result#>>'{items,0,action}'='deleted','activity action multiselect and actual actor options');
  denied:=false;BEGIN PERFORM public.brand_finance_shipping_activity(cafe,option_id,jsonb_set(jsonb_set(activity_query,'{from}',to_jsonb((today+1)::text)),'{to}',to_jsonb(today::text)));EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied,'activity reversed date range rejected');
  FOREACH input IN ARRAY ARRAY[jsonb_set(activity_query,'{actions}','["unknown"]'),jsonb_set(activity_query,'{actorIds}','["invalid"]'),jsonb_set(activity_query,'{page}','0'),jsonb_set(activity_query,'{direction}','null')] LOOP
    denied:=false;BEGIN PERFORM public.brand_finance_shipping_activity(cafe,option_id,input);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
    IF NOT denied THEN RAISE EXCEPTION 'Invalid activity query accepted';END IF;
  END LOOP;
  PERFORM pg_temp.shipping_assert(true,'activity action actor page direction validation');
  input:='{"query":"","status":"all","page":1,"sort":"displayOrder","direction":"asc"}';
  denied:=false;BEGIN PERFORM public.brand_finance_save_shipping_option(cafe,option_id,payload,23);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied,'deleted option cannot be edited');
  PERFORM set_config('request.jwt.claim.sub',foreign_actor::text,true);
  PERFORM public.brand_finance_save_shipping_option(foreign_cafe,foreign_option,jsonb_set(payload,'{accountId}','null'),0);
  PERFORM set_config('request.jwt.claim.sub',actor::text,true);
  denied:=false;BEGIN PERFORM public.brand_finance_shipping_settings(foreign_cafe);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied,'foreign tenant settings denied');
  denied:=false;BEGIN PERFORM public.brand_finance_save_shipping_option(cafe,foreign_option,jsonb_set(payload,'{accountId}','null'),0);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied AND (SELECT cafe_id FROM public.bf_shipping_options WHERE id=foreign_option)=foreign_cafe,'foreign option UUID cannot be overwritten');
  denied:=false;BEGIN PERFORM public.brand_finance_shipping_activity(cafe,foreign_option);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied,'foreign option activity not disclosed');
  SELECT p.id INTO STRICT staff_actor FROM public.profiles p WHERE p.id<>actor AND p.role<>'platform_admin' AND p.status='active' AND NOT EXISTS(SELECT 1 FROM public.bf_staff s WHERE s.cafe_id=cafe AND s.user_id=p.id) LIMIT 1;
  INSERT INTO public.bf_staff(cafe_id,user_id,name,role) VALUES(cafe,staff_actor,'العنوان الحصري - محاسب اختبار الشحن','accountant');
  PERFORM set_config('request.jwt.claim.sub',staff_actor::text,true);
  PERFORM pg_temp.shipping_assert(public.brand_finance_shipping_options(cafe,input)->>'total'='31','accountant can read shipping');
  denied:=false;BEGIN PERFORM public.brand_finance_save_shipping_option(cafe,gen_random_uuid(),payload,0);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied,'accountant cannot write shipping');
  UPDATE public.bf_staff SET role='cashier' WHERE cafe_id=cafe AND user_id=staff_actor;
  denied:=false;BEGIN PERFORM public.brand_finance_shipping_settings(cafe);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied,'cashier denied admin shipping');
  PERFORM set_config('request.jwt.claim.sub','',true);PERFORM set_config('request.jwt.claims','{}',true);
  denied:=false;BEGIN PERFORM public.brand_finance_shipping_options(cafe,input);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;
  PERFORM pg_temp.shipping_assert(denied,'anonymous denied');
  PERFORM pg_temp.shipping_assert(NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'brand_finance_%shipping%' AND (has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('service_role',p.oid,'EXECUTE') OR NOT has_function_privilege('authenticated',p.oid,'EXECUTE'))),'RPC least privilege');
  PERFORM pg_temp.shipping_assert(NOT EXISTS(SELECT 1 FROM pg_class WHERE oid IN('public.bf_shipping_settings'::regclass,'public.bf_shipping_options'::regclass,'public.bf_shipping_events'::regclass) AND (NOT relrowsecurity OR has_table_privilege('authenticated',oid,'SELECT'))),'all shipping tables private RLS');
  PERFORM pg_temp.shipping_assert((SELECT count(*) FROM public.bf_documents)=doc_count AND (SELECT count(*) FROM public.bf_journal)=journal_count AND (SELECT count(*) FROM public.bf_movements)=movement_count,'catalogue does not post financial stock or payment effects');
  SET CONSTRAINTS ALL IMMEDIATE;
END $$;
SELECT count(*) checks,jsonb_agg(to_jsonb(p) ORDER BY name) results FROM shipping_proof p;
